class ClientsComponent implements OnInit {

  searchTerm: string = '';
  clients: ClientData[] = [];
  loading: boolean = false;

  constructor(private clientService: ClientService) {}

  ngOnInit(): void {
    this.loadClients();
  }

  loadClients() {
    this.loading = true;
    this.clientService.getAllClients().subscribe({
      next: (data: ClientData[]) => {
        this.clients = data.map(c => ({
          id: c.id,
          firstName: c.firstName,
          lastName: c.lastName,
          email: c.email ?? '',
          phone: c.phone ?? '',
          reservationsCount: c.reservationsCount ?? 0,
          totalAmount: c.totalAmount ?? 0
        }));
        this.loading = false;
      },
      error: (err) => {
        console.error(err);
        this.loading = false;
      }
    });
  }

  get filteredClients(): ClientData[] {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) return this.clients;

    return this.clients.filter(client =>
      `${client.firstName} ${client.lastName}`.toLowerCase().includes(term) ||
      (client.email ?? '').toLowerCase().includes(term) ||
      (client.phone ?? '').includes(term)
    );
  }

  deleteClient(client: ClientData) {
    if (!client.id) return;

    if (confirm(`Voulez-vous vraiment supprimer le client ${client.firstName} ${client.lastName} ?`)) {
      this.clientService.deleteClient(client.id).subscribe({
        next: () => {
          this.clients = this.clients.filter(c => c.id !== client.id);
        },
        error: (err) => {
          console.error(err);
        }
      });
    }
  }
}

loadClients() {
    this.loading = true;
    this.clientService.getAllClients().subscribe({
      next: (data: ClientData[]) => {
        this.clients = data.map(c => ({
          id: c.id,
          firstName: c.firstName,
          lastName: c.lastName,
          email: c.email ?? '',
          phone: c.phone ?? '',
          reservationsCount: c.reservationsCount ?? 0,
          totalAmount: c.totalAmount ?? 0
        }));
        this.loading = false;
      },
      error: (err) => {
        console.error(err);
        this.loading = false;
      }
    });
  }

get filteredClients(): ClientData[] {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) return this.clients;

    return this.clients.filter(client =>
      `${client.firstName} ${client.lastName}`.toLowerCase().includes(term) ||
      (client.email ?? '').toLowerCase().includes(term) ||
      (client.phone ?? '').includes(term)
    );
  }

deleteClient(client: ClientData) {
    if (!client.id) return;

    if (confirm(`Voulez-vous vraiment supprimer le client ${client.firstName} ${client.lastName} ?`)) {
      this.clientService.deleteClient(client.id).subscribe({
        next: () => {
          this.clients = this.clients.filter(c => c.id !== client.id);
        },
        error: (err) => {
          console.error(err);
        }
      });
    }
  }

